echo "HTML footer written"

node -e "
const fs = require('fs');
const html = fs.readFileSync('C:/Users/13751/src/racing/index.html', 'utf8');

// Extract JS between script tags
const scriptMatch = html.match(/<script>([\s\S]*?)<\/script>/g);
if (!scriptMatch) { console.log('ERROR: No script tags found'); process.exit(1); }

// Extract all JS code (skip the first one which is just window.R = {})
let js = '';
scriptMatch.forEach(s => {
  js += s.replace(/<script>/, '').replace(/<\/script>/, '') + '\n';
});

try {
  new Function(js);
  console.log('✓ JavaScript syntax: PASS');
} catch(e) {
  console.log('✗ JavaScript syntax: FAIL');
  console.log(e.message);
}

// Check key objects
const checks = ['R.CONFIG', 'R.init', 'R.loop', 'R.updatePlayer', 'R.renderTrack', 'R.player', 'R.aiCars', 'R.track'];
checks.forEach(c => {
  if (js.includes(c)) console.log('  ✓ ' + c + ' found');
  else console.log('  ✗ ' + c + ' MISSING');
});
"

