 * R.renderOverlay()
 * Dispatch to the correct overlay based on game phase.
 */
R.renderOverlay = function () {
  var phase = R.state && R.state.phase;
  if (!phase) return;

  switch (phase) {
    case 'countdown':
      if (_countdownActive) {
        R.renderCountdown(_countdownNumber);
      }
      break;
    case 'finished':
      R.renderRaceResults();
      break;
    case 'menu':
      R._renderMenuPrompt();
      break;
  }
};

